/**
 * Shortcode to display a list of posts from a specific category.
 *
 * @param array $atts Shortcode attributes.
 * @return string HTML output of the post list.
 */
function cpl_display_category_posts( $atts ) {
    // Extract shortcode attributes with defaults
    $atts = shortcode_atts( array(
        'category' => '',
        'posts_per_page' => 5,
        'order' => 'DESC',
        'orderby' => 'date',
    ), $atts, 'category_posts' );

    // If no category is specified, return an error message
    if ( empty( $atts['category'] ) ) {
        return '<p>No category specified.</p>';
    }

    // Prepare the query arguments
    $query_args = array(
        'post_type' => 'post',
        'posts_per_page' => intval( $atts['posts_per_page'] ),
        'order' => strtoupper( $atts['order'] ),
        'orderby' => sanitize_text_field( $atts['orderby'] ),
        'category_name' => sanitize_text_field( $atts['category'] ),
    );

    // Execute the query
    $query = new WP_Query( $query_args );

    // Start building the output
    $output = '<div class="cpl-category-posts">';

    if ( $query->have_posts() ) {
        $output .= '<ul>';

        while ( $query->have_posts() ) {
            $query->the_post();

            // Get post title and permalink
            $post_title = get_the_title();
            $post_permalink = get_permalink();

            // Get post thumbnail if available
            if ( has_post_thumbnail() ) {
                $post_thumbnail = get_the_post_thumbnail( get_the_ID(), 'thumbnail' );
            } else {
                $post_thumbnail = '';
            }

            // Build the list item
            $output .= '<li>';
            $output .= '<a href="' . esc_url( $post_permalink ) . '">';
            if ( $post_thumbnail ) {
                $output .= $post_thumbnail;
            }
            $output .= esc_html( $post_title );
            $output .= '</a>';
            $output .= '</li>';
        }

        $output .= '</ul>';
    } else {
        $output .= '<p>No posts found in the specified category.</p>';
    }

    // Reset post data
    wp_reset_postdata();

    $output .= '</div>';

    return $output;
}
```

### Step 4: Register the Shortcode

Add the following line to register the shortcode:

```php
add_shortcode( 'category_posts', 'cpl_display_category_posts' );
```

### Step 5: Enqueue Styles (Optional)

If you want to style the output, you can enqueue a CSS file. Create a `style.css` file in the plugin folder with your desired styles. Then, enqueue it:

```php
/**
 * Enqueue plugin styles.
 */
function cpl_enqueue_styles() {
    wp_enqueue_style( 'cpl-style', plugin_dir_url( __FILE__ ) . 'style.css' );
}
add_action( 'wp_enqueue_scripts', 'cpl_enqueue_styles' );
```

### Step 6: Activate the Plugin

1. **Log in** to your WordPress admin dashboard.
2. Navigate to **Plugins > Installed Plugins**.
3. Find **Category Post List** and click **Activate**.

### Step 7: Use the Shortcode

Now, you can use the `[category_posts]` shortcode in your posts, pages, or widgets. Here are some examples:

- Display the latest 5 posts from the "news" category:

  ```html
  [category_posts category="news" posts_per_page="5"]
  ```

- Display the latest 10 posts from the "blog" category, ordered by title ascending:

  ```html
  [category_posts category="blog" posts_per_page="10" order="ASC" orderby="title"]
  ```

- Display all posts from the "events" category:

  ```html
  [category_posts category="events" posts_per_page="-1"]
  ```

### Additional Notes

- **Category Slug**: The `category` attribute expects the category slug (not the name). For example, if your category is "News & Updates" with a slug of `news-updates`, you would use `category="news-updates"`.
- **Error Handling**: The shortcode will display a message if no category is specified or if no posts are found.
- **Custom Styling**: Adjust the CSS in `style.css` to match your theme's design.

Enjoy your new shortcode! If you have any questions or need further customization, feel free to ask.

