```tsx
import { useState } from 'react';
import { Button, List, ListItem, ListItemText } from '@mui/material';

interface Item {
  id: string;
  name: string;
}

interface Props {
  items: Item[];
  itemsPerPage: number;
}

const ItemList = ({ items, itemsPerPage }: Props) => {
  const [visibleItems, setVisibleItems] = useState(items.slice(0, itemsPerPage));

  const handleShowMore = () => {
    const nextItems = items.slice(visibleItems.length, visibleItems.length + itemsPerPage);
    setVisibleItems([...visibleItems, ...nextItems]);
  };

  return (
    <div>
      <List>
        {visibleItems.map((item) => (
          <ListItem key={item.id}>
            <ListItemText primary={item.name} />
          </ListItem>
        ))}
      </List>
      {visibleItems.length < items.length && (
        <Button onClick={handleShowMore} variant="contained" color="primary">
          Show More
        </Button>
      )}
    </div>
  );
};

export default ItemList;
```

### Explanation

1. **Imports**: The component imports necessary modules from React and Material-UI.
2. **Item Interface**: Defines the structure of an item with `id` and `name`.
3. **Props Interface**: Defines the structure of the component's props, which includes an array of items and the number of items to display per page.
4. **State Management**: Uses the `useState` hook to manage the visible items.
5. **Show More Functionality**: The `handleShowMore` function updates the state to show more items.
6. **Rendering**: The component renders a list of visible items and a "Show More" button if there are more items to show.

### Usage

You can use this component in your Next.js pages or other components by passing the appropriate props:

```tsx
import ItemList from './ItemList';

const items = [
  { id: '1', name: 'Item 1' },
  { id: '2', name: 'Item 2' },
  // ... more items
];

const MyPage = () => {
  return (
    <div>
      <h1>My Item List</h1>
      <ItemList items={items} itemsPerPage={5} />
    </div>
  );
};

export default MyPage;
```

